// packages/api/src/lib/seed.ts
async function seedIfEmpty(db3) {
  const existing = await db3.select().from(users).limit(1);
  if (existing.length > 0) return false;
  console.log("[seed] Seeding initial data\u2026");
  const [opHash, supHash, admHash] = await Promise.all([
    import_bcryptjs.default.hash("oper123", 10),
    import_bcryptjs.default.hash("super123", 10),
    import_bcryptjs.default.hash("admin123", 10)
  ]);
  await db3.insert(users).values([
    { email: "operateur@dpi.local", passwordHash: opHash, displayName: "Op\xE9rateur DPI", role: "operator" },
    { email: "superviseur@dpi.local", passwordHash: supHash, displayName: "Superviseur DPI", role: "supervisor" },
    { email: "admin@dpi.local", passwordHash: admHash, displayName: "Admin DPI", role: "admin" }
  ]).onConflictDoNothing();
  await seedReferenceData(db3);
  console.log(`[seed] \u2713 Initial data loaded (3 users \xB7 ${roomData.length} salles \xB7 ${equipmentData.length} \xE9quipements \xB7 ${productData.length} produits \xB7 ${downtimeCategoryData.length} cat\xE9gories)`);
  return true;
}
async function seedReferenceData(db3) {
  const roomIds = {};
  for (const r2 of roomData) {
    const [row] = await db3.insert(rooms).values(r2).onConflictDoNothing().returning();
    if (row) roomIds[r2.code] = row.id;
  }
  const equipmentIds = {};
  for (const e2 of equipmentData) {
    const roomId = roomIds[e2.roomCode];
    if (!roomId) continue;
    const [row] = await db3.insert(equipments).values({
      roomId,
      code: e2.code,
      name: e2.name,
      equipmentType: e2.equipmentType,
      trsObjective: e2.trsObjective,
      defaultCadenceUnit: e2.defaultCadenceUnit
    }).onConflictDoNothing().returning();
    if (row) equipmentIds[e2.code] = row.id;
  }
  const productIds = {};
  for (const p2 of productData) {
    const [row] = await db3.insert(products).values(p2).onConflictDoNothing().returning();
    if (row) productIds[p2.code] = row.id;
  }
  for (const c2 of cadenceData) {
    const productId = productIds[c2.productCode];
    const equipmentId = equipmentIds[c2.equipmentCode];
    if (productId && equipmentId) {
      await db3.insert(productEquipmentCadences).values({
        productId,
        equipmentId,
        cadenceValue: c2.cadence,
        cadenceUnit: c2.unit
      }).onConflictDoNothing();
    }
  }
  for (const cat of downtimeCategoryData) {
    await db3.insert(downtimeCategories).values(cat).onConflictDoNothing();
  }
}

